actionConfiguration.body:
query ValidateTRN($trn: String!) {
  validateTRN(trn: $trn) {
    trn
    isValid
    formattedTrn
    message
  }
}

mutation SubmitInvoiceToETA($invoiceId: String!, $format: String) {
  submitInvoiceToETA(invoiceId: $invoiceId, format: $format) {
    success
    etaUuid
    submissionId
    canonicalHash
    qrCodeUrl
    status
    errors
    submittedAt
  }
}

actionCollections.body:
export default {
  formatCurrency: (amount) => {
    if (amount === undefined || amount === null) return '0.00 EGP';
    return Number(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' EGP';
  },
  formatTRN: (trn) => {
    if (!trn) return '';
    const digits = trn.replace(/[^0-9]/g, '');
    if (digits.length === 9) {
      return `${digits.slice(0,3)}-${digits.slice(3,6)}-${digits.slice(6,9)}`;
    }
    return trn;
  },
  calculateDailyProgress: (used, cap) => {
    if (!cap || cap === 0) return 0;
    return Math.min(100, (used / cap) * 100);
  }
}
